return [
  {
    json: {
      question: "What are the three inputs used to compute attention?",
      expectedKeywords: ["query", "key", "value"],
      shouldRefuse: false
    }
  },
  {
    json: {
      question: "How are positional encodings combined with token embeddings?",
      expectedKeywords: ["positional", "embedding", "added"],
      shouldRefuse: false
    }
  },
  {
    json: {
      question: "Why can self-attention be more parallelizable than recurrent models?",
      expectedKeywords: ["parallel", "recurrent"],
      shouldRefuse: false
    }
  },
  {
    json: {
      question: "What does the paper say about GPT-5?",
      expectedKeywords: [],
      shouldRefuse: true
    }
  }
];

const tests = [
  {
    question: "What are the three inputs used to compute attention?",
    expectedKeywords: ["query", "key", "value"],
    shouldRefuse: false
  },
  {
    question: "How are positional encodings combined with token embeddings?",
    expectedKeywords: ["positional", "embedding", "added"],
    shouldRefuse: false
  },
  {
    question: "Why can self-attention be more parallelizable than recurrent models?",
    expectedKeywords: ["parallel", "recurrent"],
    shouldRefuse: false
  },
  {
    question: "What does the paper say about GPT-5?",
    expectedKeywords: [],
    shouldRefuse: true
  }
];

const answers = $input.all();
const results = tests.map((test, index) => {
  const raw = answers[index]?.json?.output ?? answers[index]?.json?.text ?? '';
  const answer = String(raw);
  const normalized = answer.toLowerCase();

  let score = 0;
  let passed = false;
  let details = '';

  if (test.shouldRefuse) {
    const refusalSignals = [
      "i don't know based on the indexed document",
      "i don’t know based on the indexed document",
      "not in the indexed document",
      "not supported by the indexed document",
      "not present in the indexed document"
    ];
    passed = refusalSignals.some(signal => normalized.includes(signal));
    score = passed ? 1 : 0;
    details = passed ? 'Correctly refused an out-of-scope question.' : 'Expected a grounded refusal.';
  } else {
    const hits = test.expectedKeywords.filter(keyword => normalized.includes(keyword.toLowerCase()));
    score = test.expectedKeywords.length ? hits.length / test.expectedKeywords.length : 0;
    passed = score >= 0.67;
    details = `Matched ${hits.length}/${test.expectedKeywords.length} expected keywords: ${hits.join(', ') || 'none'}.`;
  }

  return {
    question: test.question,
    answer,
    score: Number(score.toFixed(2)),
    passed,
    details
  };
});

const passedCount = results.filter(r => r.passed).length;
const averageScore = results.reduce((sum, r) => sum + r.score, 0) / results.length;

return [{
  json: {
    summary: {
      tests: results.length,
      passed: passedCount,
      passRate: Number((passedCount / results.length).toFixed(2)),
      averageScore: Number(averageScore.toFixed(2))
    },
    results
  }
}];
